def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 98:
        return 'D'

    # Exploit forgiving opponents: if we defected two rounds ago and opponent cooperated in both last two rounds, defect again.
    if n >= 2 and history[-2][0] == 'D' and history[-2][1] == 'C' and history[-1][1] == 'C':
        return 'D'

    last_my, last_opp = history[-1]

    if last_opp == 'D':
        # Punish double defection
        if n >= 2 and history[-2][1] == 'D':
            return 'D'
        # Forgive if opponent has been mostly cooperative and we haven't defected much
        recent = history[-10:] if n >= 10 else history
        opp_c_recent = sum(1 for a, b in recent if b == 'C')
        my_d_recent = sum(1 for a, b in recent if a == 'D')
        if opp_c_recent >= 8 and my_d_recent <= 2:
            return 'C'
        return 'D'
    else:
        # last_opp == 'C'
        # Initial probe at round 20 (n=19) if we haven't defected yet
        if n == 19:
            my_def = sum(1 for a, b in history if a == 'D')
            if my_def == 0:
                return 'D'
        return 'C'
